/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

/**
 * Pure animation math for TextReveal. Everything in this file is
 * frame-deterministic and side-effect free so it can be unit tested.
 */

export type TextRevealUnit = "character" | "word" | "line" | "block";

export type TextRevealEffect =
  | "fade"
  | "slide"
  | "blur"
  | "scale"
  | "mask"
  | "tracking";

export type TextRevealDirection = "up" | "down" | "left" | "right";

export type TextRevealEasing =
  | "smooth"
  | "snappy"
  | "overshoot"
  | "linear"
  | "spring"
  | [number, number, number, number];

export type TextRevealExit = "none" | "mirror";

export type TextRevealPreset =
  | "soft-blur-in"
  | "per-character-rise"
  | "bottom-up-letters"
  | "top-down-letters"
  | "spring-scale-in"
  | "micro-scale-fade"
  | "scale-down-fade"
  | "blur-out-up"
  | "focus-blur-resolve"
  | "line-by-line-slide"
  | "mask-reveal-up"
  | "tracking-in"
  | "short-slide-right"
  | "staggered-fade-up";

export interface TextRevealSettings {
  unit: TextRevealUnit;
  effects: TextRevealEffect[];
  direction: TextRevealDirection;
  distance: number;
  blurAmount: number;
  scaleFrom: number;
  /** Starting letter-spacing for the `tracking` effect, in em. */
  trackingFrom: number;
  stagger: number;
  enterDuration: number;
  easing: TextRevealEasing;
  exit: TextRevealExit;
  exitDirection: TextRevealDirection;
  exitDistance: number;
  exitBlur: number;
  exitDuration: number;
  exitStagger: number;
  align: "left" | "center" | "right";
  fontSize: number;
  color: string;
  fontWeight: number | string;
  letterSpacing: string;
  speed: number;
}

export interface ExitScheduleInput {
  unitCount: number;
  enterDuration: number;
  stagger: number;
  exitDuration: number;
  exitStagger: number;
  /** Total frames available (durationInFrames * speed). */
  totalFrames: number;
}

export interface TextRevealPropsInput
  extends Partial<Omit<TextRevealSettings, "effects" | "exitDirection">> {
  text?: string;
  effects?: TextRevealEffect[] | string;
  exitDirection?: TextRevealDirection;
  preset?: TextRevealPreset | "none";
  className?: string;
}

export interface TextRevealProps {
  /** The sentence to assemble. Its first word leads the reveal. */
  text?: string;
  /** Final font size in px (the size the line settles at). */
  fontSize?: number;
  /** Overrides the design system's `foreground`. */
  color?: string;
  fontWeight?: number | string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  /** How much larger the lead word starts (2 = twice the final size). */
  initialScale?: number;
  /** Frames the lead word fades in over at the very start. */
  introDuration?: number;
  /**
   * Frames the lead word spends big and centred, drifting toward the viewer,
   * before it falls back.
   */
  holdDuration?: number;
  /** How far toward the viewer the lead word drifts during the hold (1.06 = 6% larger). */
  pushScale?: number;
  /** Frames the lead word takes to fall back from its peak to its final size. */
  recedeDuration?: number;
  /**
   * Frames the line takes to slide left into its resting place. Starts with the
   * recede but runs well past it, so the line barely moves while the lead word
   * is still falling back and only travels once it has landed.
   */
  assembleDuration?: number;
  /** Frames after the recede begins before the second word pushes in. */
  wordDelay?: number;
  /** Frames between each trailing word pushing in. */
  wordStagger?: number;
  /** Frames a trailing word takes to push into its slot. */
  wordDuration?: number;
  /** How far right of its slot a trailing word starts, in em. */
  wordPush?: number;
  /**
   * Frames a trailing word fades in over. Deliberately tiny — the word should
   * read as _pushed_ into place, not faded in. Raise it for a softer arrival.
   */
  wordFade?: number;
  /** Resting letter-spacing (CSS value, em recommended). */
  letterSpacing?: string;
  speed?: number;
  className?: string;
}

/**
 * The lead word's drift toward the viewer: decelerating, so it hangs at the
 * peak for a beat before it falls back.
 */
const PUSH_EASE = Easing.bezier(0.25, 1, 0.5, 1);

/**
 * Shared curve for the recede and the slide-left. Heavily eased in — barely 10%
 * travelled at a third of the way through — so a long `assembleDuration` keeps
 * the line practically still while the lead word falls back, then carries it
 * left and decelerates to a dead stop. No bounce.
 */
const ZOOM_EASE = Easing.bezier(0.5, 0, 0.05, 1);

/** A trailing word's push into its slot: quick off the mark, long soft landing. */
const WORD_EASE = Easing.bezier(0.22, 0.8, 0.36, 1);

/**
 * Cinematic "zoom-out from the lead word" reveal, in four beats:
 *
 * 1. The lead word fades in large and centred — close to the viewer.
 * 2. It drifts a little _closer_ still, hanging at the peak.
 * 3. It falls back to its final size, roughly in place.
 * 4. Only once it has landed does the line travel left, while the trailing words
 *    push in one by one from the right and settle.
 *
 * Beats 3 and 4 start on the same frame but run on very different clocks: the
 * recede is short, the slide is long and heavily eased in, which is what makes
 * the word read as going _back_ first and moving left second rather than doing
 * both at once. The trailing words stay invisible until `wordDelay` frames into
 * the recede — so none of them show up mid-flight while the lead word is still
 * travelling — then cut in a push-distance right of their slot and slide home.
 *
 * Only `scale`, `translate` and `opacity` animate — nothing reflows — so it
 * stays GPU-cheap with a constant baseline and no layout shift.
 */
function TextRevealScene({
  text = "Meet Acme Billing",
  fontSize = 72,
  color,
  fontWeight = 600,
  theme,
  mode,
  fontFamily,
  initialScale = 2.3,
  introDuration = 6,
  holdDuration = 12,
  pushScale = 1.06,
  recedeDuration = 14,
  assembleDuration = 30,
  wordDelay = 7,
  wordStagger = 4,
  wordDuration = 14,
  wordPush = 0.5,
  wordFade = 2,
  letterSpacing = "-0.03em",
  speed = 1,
  className,
}: TextRevealProps) {
  const frame = useCurrentFrame() * speed;
  const { width } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face =
    resolveFont(fontFamily ?? t.fontFamily) ??
    "-apple-system, BlinkMacSystemFont, sans-serif";
  const fill = color ?? t.foreground;

  // The lead word is centred in the frame while big, then lands at its natural
  // spot in the line. That needs the line's rendered width and where the lead
  // word's centre sits inside it — both constant across frames, so measure once
  // and hold the render until they're known.
  const lineRef = useRef<HTMLSpanElement>(null);
  const leadRef = useRef<HTMLSpanElement>(null);
  const [handle] = useState(() => delayRender("text-reveal: measure line"));
  const baselineRef = useRef<HTMLSpanElement>(null);
  const [metrics, setMetrics] = useState<{
    lineWidth: number;
    leadRatio: number;
    /** Distance from the top of the line box down to the text baseline. */
    baseline: number;
  } | null>(null);

  // Measure the natural line geometry. offsetWidth / offsetLeft are layout px,
  // unaffected by the animated transform or the Player's display scaling, so they
  // give the unscaled line width and the lead word's centre directly.
  useEffect(() => {
    const line = lineRef.current;
    const lead = leadRef.current;
    if (!line || !lead) {
      continueRender(handle);
      return;
    }
    const lineWidth = line.offsetWidth;
    const leadCenter = lead.offsetLeft + lead.offsetWidth / 2;
    // An empty, zero-sized inline-block sits with its bottom edge on the text
    // baseline, so its offsetTop *is* the baseline — read from the font's real
    // metrics rather than guessed from a line-height ratio.
    const baseline = baselineRef.current?.offsetTop ?? line.offsetHeight * 0.8;
    setMetrics({ lineWidth, leadRatio: leadCenter / lineWidth, baseline });
  }, [handle]);

  // Release the render only after the measurement has re-rendered, so the very
  // first captured frame already carries the correct geometry (no blank frame).
  useEffect(() => {
    if (metrics) continueRender(handle);
  }, [metrics, handle]);

  const words = text.split(" ").filter(Boolean);

  /**
   * Two things make a browser's scaled text look stuck and shaky, and both are
   * the type being quantised rather than the animation being wrong.
   *
   * **The stick.** The glyph rasteriser snaps each glyph's origin to the pixel
   * grid — quarter-pixel precision horizontally, and none at all vertically. So a
   * scale that moves the baseline makes the type climb the grid in whole-pixel
   * steps: during the slow ends of an eased curve the baseline drifts a fraction
   * of a pixel per frame, which rounds to nothing for several frames and then to a
   * whole pixel at once. Pivoting the scale *on the baseline* means the baseline's
   * device Y never changes, so there is nothing to snap.
   *
   * **The shake.** Hinting distorts each glyph's outline so its stems land on
   * whole pixels. As the size slides, every stem re-snaps to a different grid and
   * the letterforms visibly change shape frame to frame — they boil.
   * `text-rendering: geometricPrecision` turns hinting off and renders the outline
   * as it actually is.
   *
   * Measured on the sibling component: vertical judder 0.296px → 0.005px, and the
   * shape invariant steadied from 3.41% drift to 0.22%.
   */

  const ready = metrics !== null;
  const leadRatio = metrics?.leadRatio ?? 0.14;
  const lineWidth = metrics?.lineWidth ?? width * 0.5;
  // Distance from the top of the line box down to the text baseline — the one
  // point the scale must not move.
  const baseline = metrics?.baseline ?? fontSize * 0.88;

  // The lead word falls back and the line starts sliding on the same frame.
  const zoomStart = holdDuration;
  // How far the line has to travel to carry the lead word's centre from the
  // frame centre to its natural spot in the sentence.
  const slideDistance = lineWidth * (0.5 - leadRatio);

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        ref={lineRef}
        className={className}
        style={{
          position: "relative",
          display: "inline-block",
          fontSize,
          fontWeight,
          color: fill,
          letterSpacing,
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          fontFamily: face,
          // Pivot on the lead word's centre horizontally — so the line scales out
          // from that word and it stays planted — and on the baseline vertically,
          // which is the point that must not move. See above.
          transformOrigin: `${leadRatio * 100}% ${baseline}px`,
          // Drift toward the viewer, then the fall back. The two curves never
          // overlap — the first clamps at the peak once the recede starts, the
          // second is 0 until then — so they sum into one continuous scale
          // running initialScale → peak → 1.
          scale:
            interpolate(
              frame,
              [0, holdDuration],
              [initialScale, initialScale * pushScale],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: PUSH_EASE,
              },
            ) +
            interpolate(
              frame,
              [zoomStart, zoomStart + recedeDuration],
              [0, 1 - initialScale * pushScale],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: ZOOM_EASE,
              },
            ),
          // The slide left: same start frame as the recede, but it runs about
          // twice as long on a heavily eased-in curve, so the line holds its
          // ground while the lead word falls back and only travels once it has
          // landed.
          translate: `${interpolate(
            frame,
            [zoomStart, zoomStart + assembleDuration],
            [slideDistance, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: ZOOM_EASE,
            },
          )}px`,
          opacity: ready ? 1 : 0,
          // Hinting off: renders each outline as it actually is, so the
          // letterforms stop re-snapping to the pixel grid as the size slides.
          // Also forces sub-pixel glyph positioning, which Blink otherwise only
          // enables above a device scale factor of 1 — and a render is exactly 1.
          textRendering: "geometricPrecision",
          // Rendering and live playback want opposite things here, so give each
          // what it needs.
          //
          // A render has no time budget: the browser re-shapes and re-rasterises
          // every glyph at every new size, which is why the type stays genuinely
          // crisp, and the two fixes above are what make that smooth. Compositing
          // it would only replace real type with a rescaled texture — and worse,
          // a render is spread across parallel browser tabs, each of which
          // inherits a stale raster from whatever scale it drew last, so the same
          // frame comes out differently depending on which tab drew it.
          //
          // The Player is the opposite: one continuous tab, and roughly eight
          // milliseconds a frame on a 120Hz screen. Re-shaping a line of type at
          // a brand-new size every frame is the most expensive way to draw text,
          // and a frame that misses the budget is simply shown for the wrong
          // length of time — stutter that no amount of CSS can fix. So for live
          // playback, hand the scale to the compositor: measured on a single
          // continuous tab it is smooth (0.016px of judder) with no loss of
          // sharpness at all.
          ...(getRemotionEnvironment().isRendering
            ? null
            : { willChange: "transform" as const }),
        }}
      >
        {words.map((word, i) => {
          const isLead = i === 0;
          // Each trailing word sits out most of the recede, then pushes in from
          // the right into its slot. The lead word is the anchor: it never
          // pushes, and it is the only word visible until `wordDelay`.
          const pushStart = zoomStart + wordDelay + (i - 1) * wordStagger;
          const opacity = isLead
            ? interpolate(frame, [0, introDuration], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : interpolate(frame, [pushStart, pushStart + wordFade], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
          return (
            <span
              // biome-ignore lint/suspicious/noArrayIndexKey: words are positional and never reorder
              key={i}
              ref={isLead ? leadRef : undefined}
              style={{
                display: "inline-block",
                opacity,
                translate: isLead
                  ? undefined
                  : `${interpolate(
                      frame,
                      [pushStart, pushStart + wordDuration],
                      [wordPush * fontSize, 0],
                      {
                        extrapolateLeft: "clamp",
                        extrapolateRight: "clamp",
                        easing: WORD_EASE,
                      },
                    )}px`,
              }}
            >
              {word}
              {i < words.length - 1 ? " " : ""}
            </span>
          );
        })}
        {/* Baseline ruler. An empty, zero-sized inline-block aligns its bottom
            edge to the text baseline, so `offsetTop` reads the baseline straight
            off the font's real metrics. Zero-sized, so it changes no layout. */}
        <span
          ref={baselineRef}
          style={{ display: "inline-block", width: 0, height: 0 }}
        />
      </span>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type TextRevealElementProps = Omit<
  ComponentProps<typeof TextRevealScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const TextRevealDefaults = {
  text: "Meet Acme Billing",
  fontSize: 72,
  color: "#101828",
  fontWeight: 600,
  initialScale: 2.3,
  pushScale: 1.06,
  introDuration: 6,
  holdDuration: 12,
  recedeDuration: 14,
  assembleDuration: 30,
  wordDelay: 7,
  wordStagger: 4,
  wordDuration: 14,
  wordPush: 0.5,
  wordFade: 2,
  speed: 1,
} satisfies Partial<TextRevealElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const TextRevealSchema = {
  text: {
    type: "text-content",
    default: "Meet Acme Billing",
    description: "Text",
  },
  fontSize: {
    type: "number",
    default: 72,
    min: 12,
    max: 160,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
    keyframable: false,
  },
  color: {
    type: "color",
    default: "#101828",
    description: "Color",
    keyframable: false,
  },
  fontWeight: {
    type: "number",
    default: 600,
    min: 400,
    max: 700,
    step: 100,
    description: "Font weight",
    hiddenFromList: false,
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function TextRevealFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const TextRevealInner = forwardRef<HTMLDivElement, TextRevealElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...TextRevealDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={820}
        height={240}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 820,
            height: 240,
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <TextRevealFade>
            <TextRevealScene key={key} {...rest} />
          </TextRevealFade>
        </div>
      </Sequence>
    );
  },
);

export const TextReveal = Interactive.withSchema({
  Component: TextRevealInner,
  componentName: "<TextReveal>",
  schema: TextRevealSchema,
  wrapInSequence: true,
});
